-- ============================================================================
-- StayHub 전시회 시연용 데모 데이터 (손으로 한 번 실행하는 SQL. 앱이 자동으로 넣지 않음)
--
-- * 먼저 앱을 한 번 켜서 테이블·기본 데이터(data.sql)를 만든 뒤 실행하세요.
-- * 여러 번 실행해도 결과가 같습니다. 데모 행은 ID 900001~900999 이고, 맨 앞에서 그 범위만 지운 뒤 다시 넣습니다.
--   (숙소 1번·숙소 시설 연결은 지우지 않고 UPDATE / 있으면 건너뜀)
-- * 날짜는 전부 오늘(CURDATE()/NOW()) 기준 상대값입니다. 다시 실행하면 오늘 기준으로 다시 맞춰집니다.
-- * 결제 수수료·실매출은 PaymentService 와 같은 방식(채널 수수료율, 소수 둘째 자리 반올림)으로
--   channels 테이블 값을 읽어 계산합니다(아래 UPDATE).
-- * 시연 계정 비밀번호: Demo1234!  (demo_host · demo_staff · demo_front · demo_cleaning)
--
-- 실행 방법·계정·건수 표는 docs/demo/README.md 참고.
-- ============================================================================

SET NAMES utf8mb4;
START TRANSACTION;

-- 1) 데모 범위 지우기 (자식 → 부모 순서)
DELETE FROM messages            WHERE message_id     BETWEEN 900001 AND 900999;
DELETE FROM message_threads     WHERE thread_id      BETWEEN 900001 AND 900999;
DELETE FROM special_requests    WHERE request_id     BETWEEN 900001 AND 900999;
DELETE FROM additional_charges  WHERE charge_id      BETWEEN 900001 AND 900999;
DELETE FROM payments            WHERE payment_id     BETWEEN 900001 AND 900999;
DELETE FROM housekeeping_tasks  WHERE task_id        BETWEEN 900001 AND 900999;
DELETE FROM reservations        WHERE reservation_id BETWEEN 900001 AND 900999;
DELETE FROM guidebooks          WHERE guidebook_id   BETWEEN 900001 AND 900999;
DELETE FROM rooms               WHERE room_id        BETWEEN 900001 AND 900999;
DELETE FROM channels            WHERE channel_id     BETWEEN 900001 AND 900999;
DELETE FROM users               WHERE user_id        BETWEEN 900001 AND 900999;

-- 2) 시연 계정 4개 (비밀번호 Demo1234!, BCrypt 해시는 프로젝트 PasswordEncoder 로 생성)

-- 3) 숙소 1번: 공개(PUBLISHED) + 소개 문구. 이미 있으면 UPDATE
모든 객실에서 바다 또는 소나무 숲을 볼 수 있고, 해변까지 걸어서 3분이면 닿습니다.
무료 주차와 와이파이, 아침 조식을 제공합니다.', 'PUBLISHED', NULL, NOW(), NOW())
ON DUPLICATE KEY UPDATE property_name = VALUES(property_name), description = VALUES(description),
  status = VALUES(status), updated_at = NOW();

-- 숙소 시설 연결 (시설 코드는 data.sql 이 넣음). 이미 연결돼 있으면 그대로
ON DUPLICATE KEY UPDATE updated_at = updated_at;

-- 4) 가이드북 5건 (ACTIVE)
늦은 체크인은 프런트에 미리 알려 주세요.', 1, 'ACTIVE', TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL -30 DAY), '10:00:00'), TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL -30 DAY), '10:00:00')),
(900002, 1, 'PARKING', '주차 안내', '건물 뒤편 전용 주차장(20대)을 무료로 이용하실 수 있습니다.
객실당 1대 기준이며, 추가 차량은 프런트에 문의해 주세요.', 2, 'ACTIVE', TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL -30 DAY), '10:00:00'), TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL -30 DAY), '10:00:00')),
(900003, 1, 'WIFI', '와이파이', '네트워크: StayHub_Guest
비밀번호: 객실 안 안내 카드에 적혀 있습니다.', 3, 'ACTIVE', TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL -30 DAY), '10:00:00'), TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL -30 DAY), '10:00:00')),
(900004, 1, 'CHECKIN', '셀프 체크인 방법', '프런트가 비어 있을 때는 예약 문자로 받은 객실 번호와 출입 비밀번호로 바로 들어가실 수 있습니다.', 4, 'ACTIVE', TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL -30 DAY), '10:00:00'), TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL -30 DAY), '10:00:00')),
(900005, 1, 'ETC', '주변 편의 시설', '편의점: 정문에서 도보 2분
해수욕장: 도보 3분
조식: 1층 라운지 오전 7시~9시 30분', 5, 'ACTIVE', TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL -30 DAY), '10:00:00'), TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL -30 DAY), '10:00:00'));

-- 5) OTA 채널 3개 추가 (기존 1·2번은 그대로). 등록 채널, 수수료율 서로 다르게

-- 6) 객실 20개 (2~5층). 오늘 상태: 투숙 중 OCCUPIED · 청소 필요 CLEANING_NEEDED · 청소 중 CLEANING · 빈 방 VACANT

-- 7) 예약 50건 (오늘 -30일 ~ +30일). 예약번호 R{체크인날짜}-DEMO0001 형식

-- 8) 결제. 취소·노쇼를 뺀 예약 대부분에 결제 완료(COMPLETED). 취소 2건은 환불 완료
--    결제 수단: 채널 예약은 '사전 결제'(예약 때), 채널 없는 게스트 직접 예약은 '현장 결제'(체크인 때, 1번 직접 예약 채널). 체크인 전 직접 예약은 결제 없음
--    (체크인 3일 전까지 요청 → 전액 REFUNDED / 이후 → 50% PARTIALLY_REFUNDED)

-- 수수료·실매출: PaymentService.calculateCommission 과 같은 계산
--   등록 채널이면 commission_rate, 미등록이면 default_commission_rate. 결제 금액 × 율 / 100, 소수 둘째 자리 반올림(HALF_UP)
UPDATE payments p JOIN channels c ON c.channel_id = p.channel_id
SET p.commission_amount = ROUND(p.payment_amount * IF(c.is_registered, c.commission_rate, c.default_commission_rate) / 100, 2),
    p.net_revenue = p.payment_amount - ROUND(p.payment_amount * IF(c.is_registered, c.commission_rate, c.default_commission_rate) / 100, 2)
WHERE p.payment_id BETWEEN 900001 AND 900999;

-- 9) 추가 요금 4건

-- 10) 특별 요청 3건

-- 11) 오늘 청소 작업 5건 (담당: demo_cleaning)

-- 12) 메시지 스레드 3개 (예약과 연결). 900001·900003 은 마지막이 게스트 메시지(수동 응대 필요)


COMMIT;

-- ============================================================================
-- 확인 1) 같은 객실에서 날짜가 겹치는 예약 (취소·노쇼 제외, ReservationService 와 같은 규칙). 0행이어야 정상
SELECT a.room_id, a.reservation_id AS a_id, b.reservation_id AS b_id,
       a.check_in_date AS a_in, a.check_out_date AS a_out, b.check_in_date AS b_in, b.check_out_date AS b_out
FROM reservations a
JOIN reservations b
  ON a.room_id = b.room_id AND a.reservation_id < b.reservation_id
 AND a.check_in_date < b.check_out_date AND a.check_out_date > b.check_in_date
WHERE a.room_id BETWEEN 900001 AND 900999
  AND a.status NOT IN ('CANCELLED', 'NOSHOW') AND b.status NOT IN ('CANCELLED', 'NOSHOW');

-- 확인 2) 넣은 건수
SELECT 'users' AS tbl, COUNT(*) AS cnt FROM users WHERE user_id BETWEEN 900001 AND 900999
UNION ALL SELECT 'channels', COUNT(*) FROM channels WHERE channel_id BETWEEN 900001 AND 900999
UNION ALL SELECT 'guidebooks', COUNT(*) FROM guidebooks WHERE guidebook_id BETWEEN 900001 AND 900999
UNION ALL SELECT 'rooms', COUNT(*) FROM rooms WHERE room_id BETWEEN 900001 AND 900999
UNION ALL SELECT 'reservations', COUNT(*) FROM reservations WHERE reservation_id BETWEEN 900001 AND 900999
UNION ALL SELECT 'payments', COUNT(*) FROM payments WHERE payment_id BETWEEN 900001 AND 900999
UNION ALL SELECT 'additional_charges', COUNT(*) FROM additional_charges WHERE charge_id BETWEEN 900001 AND 900999
UNION ALL SELECT 'special_requests', COUNT(*) FROM special_requests WHERE request_id BETWEEN 900001 AND 900999
UNION ALL SELECT 'housekeeping_tasks', COUNT(*) FROM housekeeping_tasks WHERE task_id BETWEEN 900001 AND 900999
UNION ALL SELECT 'message_threads', COUNT(*) FROM message_threads WHERE thread_id BETWEEN 900001 AND 900999
UNION ALL SELECT 'messages', COUNT(*) FROM messages WHERE message_id BETWEEN 900001 AND 900999;
